include install_aide

class install_aide {
  package { 'aide':
    ensure => 'installed',
  }
}

include install_crypto-policies

class install_crypto-policies {
  package { 'crypto-policies':
    ensure => 'installed',
  }
}

include install_sudo

class install_sudo {
  package { 'sudo':
    ensure => 'installed',
  }
}

include remove_gssproxy

class remove_gssproxy {
  package { 'gssproxy':
    ensure => 'purged',
  }
}

include install_authselect

class install_authselect {
